<?php
/** Unified group/tag/author administration with immutable IDs, bounded fields and in-use deletion protection; original Blog catalogs are never rewritten. */
declare(strict_types=1);
use function DBLESSCMS\e;
$entry=$id===''?null:($terms[$route][$id]??throw new \DBLESSCMS\HttpError(404,'Entry unavailable.','posts.error.missing'));
?>
<div class="posts-library"><section class="panel"><div class="table-scroll"><table class="extension-table"><caption class="sr-only"><?= e($t($route)) ?></caption><thead><tr><th><?= e($t('entryName')) ?></th><th><?= e($t('identifier')) ?></th><th><?= e($t('actions')) ?></th></tr></thead><tbody>
<?php foreach($terms[$route] as $key=>$term):if($term['deleted'])continue; ?><tr><td><?= e($term['name']) ?></td><td><?= e($key) ?></td><td><div class="row-actions"><?= \DBLESSCMS\AdminTable::action($url($route,['id'=>$key]),'edit',$t('edit'),$context->base) ?><form method="post" action="<?= e($context->url('term-remove')) ?>" data-pages-form data-confirm="<?= e($t('confirm')) ?>"><?php $hidden($key); ?><button class="icon-button" title="<?= e($t('entryRemove')) ?>" aria-label="<?= e($t('entryRemove')) ?>"><?= \DBLESSCMS\Icons::svg('uninstall',$context->base) ?></button></form></div></td></tr><?php endforeach; ?></tbody></table></div><a class="text-link" href="<?= e($url($route)) ?>"><?= e($t('newEntry')) ?></a></section>
<form class="panel" method="post" action="<?= e($context->url('term-save')) ?>" data-pages-form><?php $hidden($id); ?><input type="hidden" name="original" value="<?= e($id) ?>"><h2><?= e($t($id===''?'newEntry':'edit')) ?></h2><label><?= e($t('entryName')) ?><input name="name" maxlength="160" required value="<?= e($entry['name']??'') ?>" data-post-entry-name></label><label><?= e($t('identifier')) ?><input name="termId" maxlength="64" pattern="[a-z][a-z0-9\-]{0,63}" required value="<?= e($id) ?>" <?= $id!==''?'readonly':'data-post-entry-id' ?>></label>
<?php if($route==='authors'): ?><label><?= e($t('bio')) ?><textarea name="bio" maxlength="2000" rows="5"><?= e($entry['bio']??'') ?></textarea></label><label><?= e($t('image')) ?><input name="profileImage" maxlength="512" value="<?= e($entry['image']??'') ?>"></label><label><?= e($t('profileUrl')) ?><input type="url" name="profileUrl" maxlength="2048" value="<?= e($entry['url']??'') ?>"></label>
<?php else: ?><label><?= e($t('descriptionField')) ?><textarea name="description" maxlength="1000" rows="5"><?= e($entry['description']??'') ?></textarea></label><?php if($route==='groups'): ?><label><?= e($t('parent')) ?><select name="parent" aria-label="<?= e($t('parent')) ?>"><option value=""><?= e($t('none')) ?></option><?php foreach($terms['groups'] as $key=>$group):if($key===$id||$group['deleted'])continue; ?><option value="<?= e($key) ?>" <?= ($entry['parent']??'')===$key?'selected':'' ?>><?= e($group['name']) ?></option><?php endforeach; ?></select></label><?php endif;endif; ?>
<div class="savebar"><button class="button-primary"><?= e($t('termSave')) ?></button></div></form></div>
